python3 -c "
import json, os
d = '/root/acr-vla-conformal-refinement/logs'
for f in sorted(os.listdir(d)):
    if f.startswith('eval_') and f.endswith('.json'):
        try:
            data = json.load(open(os.path.join(d, f)))
            info = {k: data.get(k) for k in ['method','max_correction_norm','seed','overall_sr','successes','rollouts']}
            info['file'] = f
            print(json.dumps(info, default=str))
        except Exception as e:
            print(json.dumps({'file': f, 'error': str(e)}))
"

